PRAGMA threads=3; PRAGMA cache_size=100; CREATE TABLE result(run INTEGER NOT NULL,a,c1,b); CREATE TABLE state(run INTEGER NOT NULL,n INTEGER NOT NULL); INSERT INTO state VALUES(0,0); CREATE VIEW sink AS SELECT a,c1,b FROM result; CREATE TRIGGER sink_insert INSTEAD OF INSERT ON sink WHEN (SELECT n FROM state)<10 BEGIN INSERT INTO result(run,a,c1,b) VALUES((SELECT run FROM state),NEW.a,NEW.c1,NEW.b); UPDATE state SET n=n+1; END; UPDATE state SET run=1,n=0; INSERT INTO sink(a,c1,b) SELECT a,c1,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=2,n=0; INSERT INTO sink(a,c1,b) SELECT a,c1,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=3,n=0; INSERT INTO sink(a,c1,b) SELECT a,c1,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=4,n=0; INSERT INTO sink(a,c1,b) SELECT a,c1,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=5,n=0; INSERT INTO sink(a,c1,b) SELECT a,c1,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=6,n=0; INSERT INTO sink(a,c1,b) SELECT a,c1,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=7,n=0; INSERT INTO sink(a,c1,b) SELECT a,c1,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=8,n=0; INSERT INTO sink(a,c1,b) SELECT a,c1,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=9,n=0; INSERT INTO sink(a,c1,b) SELECT a,c1,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=10,n=0; INSERT INTO sink(a,c1,b) SELECT a,c1,b FROM t1 WHERE rowid<=100000 ORDER BY a;